import{_ as d,c as e,o,ae as a}from"./chunks/framework.DUl3UDQb.js";const y=JSON.parse('{"title":"hy 常见操作 × 三平台使用对照表","description":"","frontmatter":{},"headers":[],"relativePath":"AI赋能/hy插件/commands-matrix.md","filePath":"AI赋能/hy插件/commands-matrix.md"}'),r={name:"AI赋能/hy插件/commands-matrix.md"};function h(c,t,l,n,s,i){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="hy-常见操作-×-三平台使用对照表" tabindex="-1">hy 常见操作 × 三平台使用对照表 <a class="header-anchor" href="#hy-常见操作-×-三平台使用对照表" aria-label="Permalink to &quot;hy 常见操作 × 三平台使用对照表&quot;">​</a></h1><blockquote><p>hy 工作流插件三平台适配（Claude Code ✅ / Codex 🔧 / CodeBuddy 🔧）的常见操作对照。 核心差异一句话：<strong>Claude Code 与 CodeBuddy 用斜杠命令触发，Codex 没有斜杠命令，用自然语言触发</strong>。 Codex 的触发语句只要包含「hy + 流程名」关键词即可命中（AGENTS.md 中登记了完整映射）。</p></blockquote><h2 id="_1-安装与调试" tabindex="-1">1. 安装与调试 <a class="header-anchor" href="#_1-安装与调试" aria-label="Permalink to &quot;1. 安装与调试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Claude Code</th><th>Codex</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>同事一键安装</td><td><code>curl -fsSL http://10.1.34.16:30021/AI赋能/hy插件/install.sh | sh</code></td><td><code>curl -fsSL http://10.1.34.16:30021/AI赋能/hy插件-codex/install.sh | sh</code></td><td><code>curl -fsSL http://10.1.34.16:30021/AI赋能/hy插件-codebuddy/install.sh | sh</code></td></tr><tr><td>安装后必须做的事</td><td>无（装完即生效）</td><td><strong>运行 <code>/hooks</code> 逐个批准 hook 信任</strong>（否则门禁不生效）</td><td>项目级技能需放工作区根 <code>.codebuddy/skills/</code></td></tr><tr><td>开发调试（免安装）</td><td><code>/plugin marketplace add &lt;repo路径&gt;/claudeCode</code> + <code>/plugin install hy</code></td><td>复制 <code>codex/</code> 内容到 <code>~/.codex/</code></td><td><code>codebuddy --plugin-dir &lt;repo路径&gt;/codeBuddy</code></td></tr><tr><td>更新</td><td><code>/hy:update</code>（给指引，人工执行）</td><td>重新运行安装器覆盖</td><td><code>/hy:update</code> 或重新运行安装器</td></tr></tbody></table><h2 id="_2-跑开发流程" tabindex="-1">2. 跑开发流程 <a class="header-anchor" href="#_2-跑开发流程" aria-label="Permalink to &quot;2. 跑开发流程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>Claude Code</th><th>Codex（自然语言触发）</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>自动路由（拿不准走哪个流程）</td><td><code>/hy:run &lt;需求&gt;</code>（不带参数显示全部流程目录）</td><td>「运行 hy 自动路由：&lt;需求&gt;」</td><td><code>/hy:run &lt;需求&gt;</code></td></tr><tr><td>统计展示（图表 + 统计卡片）</td><td><code>/hy:run-stats &lt;需求&gt;</code></td><td>「运行 hy 统计展示流水线：&lt;需求&gt;」</td><td><code>/hy:run-stats &lt;需求&gt;</code></td></tr><tr><td>增删改查页</td><td><code>/hy:run-crud &lt;需求&gt;</code></td><td>「运行 hy 增删改查流水线：&lt;需求&gt;」</td><td><code>/hy:run-crud &lt;需求&gt;</code></td></tr><tr><td>数据大屏</td><td><code>/hy:run-screen &lt;需求&gt;</code></td><td>「运行 hy 大屏页开发流水线：&lt;需求&gt;」</td><td><code>/hy:run-screen &lt;需求&gt;</code></td></tr><tr><td>全栈开发（PRD→蓝图→编码→验收）</td><td><code>/hy:run-all &lt;需求&gt;</code></td><td>「运行 hy 全栈工作流：&lt;需求&gt;」</td><td><code>/hy:run-all &lt;需求&gt;</code></td></tr><tr><td>v1→v2 页面迁移</td><td><code>/hy:migration &lt;需求&gt;</code></td><td>「运行 hy v1→v2 迁移流水线：&lt;需求&gt;」</td><td><code>/hy:migration &lt;需求&gt;</code></td></tr></tbody></table><h2 id="_3-委派专家" tabindex="-1">3. 委派专家 <a class="header-anchor" href="#_3-委派专家" aria-label="Permalink to &quot;3. 委派专家&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Claude Code</th><th>Codex</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>直接调用专家（改搜索框、修接口等局部操作）</td><td><code>@hy:frontend 改用户列表搜索框</code></td><td>「spawn hy 的 frontend 专家：改用户列表搜索框」</td><td><code>@hy:frontend 改用户列表搜索框</code></td></tr><tr><td>可用专家</td><td><code>@hy:product / design / lead / backend / frontend / ui / db / test</code></td><td>同名子代理（<code>codex/agents/*.toml</code>，自动转换）</td><td>同 Claude Code 名称</td></tr></tbody></table><blockquote><p>Codex 专家 spawn 语：Codex 会话中直接说「用 hy 的 backend 专家实现 XX」即可，Codex 会按 <code>developer_instructions</code> 加载专家提示词。多专家并行靠 Codex 原生子代理（Agent Teams 是 CC 专属）。</p></blockquote><h2 id="_4-管理命令" tabindex="-1">4. 管理命令 <a class="header-anchor" href="#_4-管理命令" aria-label="Permalink to &quot;4. 管理命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Claude Code</th><th>Codex</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>查看版本</td><td><code>/hy:version</code></td><td>「查看 hy 插件版本」</td><td><code>/hy:version</code></td></tr><tr><td>帮助（命令/专家/门禁/安装）</td><td><code>/hy:help</code></td><td>「展示 hy 插件帮助」</td><td><code>/hy:help</code></td></tr><tr><td>检查更新</td><td><code>/hy:update</code></td><td>「检查 hy 插件更新」</td><td><code>/hy:update</code></td></tr></tbody></table><h2 id="_5-门禁与约束" tabindex="-1">5. 门禁与约束 <a class="header-anchor" href="#_5-门禁与约束" aria-label="Permalink to &quot;5. 门禁与约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Claude Code</th><th>Codex</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>门禁生效方式</td><td>装即生效（hooks.json）</td><td><strong>需 <code>/hooks</code> 批准信任</strong>后才执行</td><td>hooks 配置合并到 <code>~/.codebuddy/settings.json</code>；<strong>PostToolUse 无阻止能力</strong>（拦截靠 PreToolUse）</td></tr><tr><td>AI 执行 git 提交</td><td>❌ commit-gate 拦截，交人工</td><td>❌ 同左（批准信任后）</td><td>❌ 同左</td></tr><tr><td>风格红线（console.log 等）</td><td>PostToolUse 拦截回传</td><td>PostToolUse 反馈（apply_patch 需适配）</td><td>弱拦截（仅回传提示，PreToolUse 适配中）</td></tr><tr><td>紧急绕过（人工授权）</td><td><code>HCODEr_SKIP_GATE=1</code>（代提交）/ <code>HCODEr_SKIP_STYLE=1</code>（风格）</td><td>同左</td><td>同左</td></tr><tr><td>数据库变更</td><td>DDL/DML 只出方案，人工执行（三家一致）</td><td>同左</td><td>同左</td></tr><tr><td>交付标准</td><td>人工验收通过才算交付（三家一致）</td><td>同左</td><td>同左</td></tr></tbody></table><h2 id="_6-规范加载-宪法" tabindex="-1">6. 规范加载（宪法） <a class="header-anchor" href="#_6-规范加载-宪法" aria-label="Permalink to &quot;6. 规范加载（宪法）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Claude Code</th><th>Codex</th><th>CodeBuddy</th></tr></thead><tbody><tr><td>规范加载机制</td><td>constitution 技能：地图 + 按域正文，用时才读</td><td>同（<code>skills/constitution/</code> 直接复用）+ AGENTS.md 全局指令</td><td>同 Claude Code</td></tr><tr><td>项目级规范</td><td><code>.claude/design/</code>、<code>__aiDev__/</code></td><td>同（路径无关平台）</td><td>同</td></tr></tbody></table><h2 id="使用注意事项-按平台" tabindex="-1">使用注意事项（按平台） <a class="header-anchor" href="#使用注意事项-按平台" aria-label="Permalink to &quot;使用注意事项（按平台）&quot;">​</a></h2><h3 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h3><ol><li><strong>没有斜杠命令</strong>：所有 <code>/hy:*</code> 用自然语言替代（上表已列触发语句），说清楚「hy + 流程名 + 需求」即可</li><li><strong>装完必须 <code>/hooks</code> 批准</strong>：不批准 = 门禁不执行（commit-gate 失效，AI 可能直接 push）</li><li>全局 skills 在 <code>~/.codex/skills/</code>；项目级放仓库 <code>.codex/</code></li></ol><h3 id="codebuddy" tabindex="-1">CodeBuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;CodeBuddy&quot;">​</a></h3><ol><li>命令/技能格式与 Claude Code 兼容，肌肉记忆直接可用（<code>/hy:run-crud</code> 等）</li><li>项目级技能必须放<strong>工作区根目录</strong> <code>.codebuddy/skills/</code></li><li>风格门禁为提示级（PostToolUse 不能阻止），真正拦截靠 PreToolUse —— 深度依赖门禁的场景优先用 Claude Code</li></ol><h3 id="三平台通用" tabindex="-1">三平台通用 <a class="header-anchor" href="#三平台通用" aria-label="Permalink to &quot;三平台通用&quot;">​</a></h3><ul><li>内容和规范完全一致（shared 唯一源构建），同一份宪法/流水线/专家提示词</li><li>绕过变量、交付标准、数据库边界一致</li></ul>',22)]))}const b=d(r,[["render",h]]);export{y as __pageData,b as default};
